// @generated by:gauntlet run:godseye-local-coding-runners
import { randomBytes, randomUUID } from "node:crypto";
import {
  CONTROL_API_HEADER,
  CONTROL_API_VERSION,
  type PrepareCodingTaskInput,
} from "@godseye/contracts";
import { AccessBroker, InfrastructureEngine } from "@godseye/core";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createApp } from "../apps/control-api/src/app.js";
import { codingStartupOptions } from "../apps/control-api/src/coding-startup.js";
import { loadConfiguration } from "../apps/control-api/src/config.js";
import { createControlClient } from "../packages/control-client/src/index.js";
import { MemoryAccessProvider } from "./access-helpers.js";
import { owner, projectInput, repository } from "./helpers.js";
import { type OwnerAuthFixture, ownerAuthFixture } from "./owner-auth-fixture.js";

describe("coding owner routes and typed client against real authenticated HTTP", () => {
  let f: OwnerAuthFixture;
  let headers: Headers;
  let engine: InfrastructureEngine;
  let app: ReturnType<typeof createApp>;
  let broker: AccessBroker;
  beforeEach(async () => {
    f = await ownerAuthFixture();
    headers = (await f.session()).headers;
    headers.set(CONTROL_API_HEADER, CONTROL_API_VERSION);
    engine = new InfrastructureEngine(f.store);
    broker = new AccessBroker(f.store, {
      foundation: engine.foundation,
      provider: new MemoryAccessProvider(),
      fingerprintKey: randomBytes(48).toString("base64url"),
    });
    app = createApp(
      f.core,
      loadConfiguration({ GODSEYE_MODE: "local" }),
      f.identity,
      engine.foundation,
      broker,
      engine,
    );
  });
  afterEach(async () => f.close());
  const routes = () =>
    [
      ["GET", "/agents/coding"],
      ["POST", "/agents/coding/preparations"],
      ["GET", `/agents/coding/preparations/${randomUUID()}`],
      ["POST", "/agents/coding/tasks"],
      ["GET", `/agents/coding/tasks/${randomUUID()}`],
      ["POST", `/agents/coding/tasks/${randomUUID()}/cancel`],
      ["POST", `/agents/coding/tasks/${randomUUID()}/reconcile`],
    ] as const;
  const client = () =>
    createControlClient({
      baseUrl: f.origin,
      headers,
      fetch: async (input, init) => app.request(new Request(input, init)),
    });
  const post = (path: string, body: unknown, key = randomUUID(), requestHeaders = headers) =>
    app.request(new URL(`/api/v1${path}`, f.origin), {
      method: "POST",
      headers: new Headers([...requestHeaders, ["idempotency-key", key]]),
      body: JSON.stringify(body),
    });
  async function input(): Promise<PrepareCodingTaskInput> {
    const created = await f.core.createProject(owner, projectInput, randomUUID());
    const project = await f.core.configureRepository(
      owner,
      created.id,
      repository,
      created.revision,
      randomUUID(),
    );
    const environment = project.environments.find((value) => value.kind === "development");
    if (!environment) throw new Error("Missing coding HTTP environment");
    return {
      projectId: project.id,
      environmentId: environment.id,
      expectedProjectRevision: project.revision,
      expectedEnvironmentRevision: environment.revision,
      runner: "claude-code",
      commitSha: "a".repeat(40),
      input: "Synthetic owner intent",
      testProfile: "none",
      previewRequested: false,
      limits: {
        timeoutSeconds: 30,
        maxCostMicros: 10000,
        maxPatchBytes: 1000,
        maxOutputBytes: 1000,
      },
    };
  }
  it("T-AC-781 authenticates every coding route before interpreting input", async () => {
    for (const [method, path] of routes()) {
      const response = await app.request(new URL(`/api/v1${path}`, f.origin), {
        method,
        headers: f.headers(),
        ...(method === "GET" ? {} : { body: "{malformed" }),
      });
      expect(response.status).toBe(401);
    }
  });
  it("T-AC-781 rejects a genuine service identity at all coding owner routes", async () => {
    const scope = await input();
    const actor = await f.identity.actor(headers);
    if (!actor) throw new Error("Missing owner actor");
    const identity = await broker.createIdentity(
      actor,
      {
        projectId: scope.projectId,
        environmentId: scope.environmentId,
        purpose: "runtime",
        name: "Synthetic coding service",
      },
      randomUUID(),
    );
    let proof = "";
    await broker.issueProof(actor, identity.id, identity.revision, randomUUID(), (value) => {
      proof = value;
    });
    for (const [method, path] of routes()) {
      const response = await app.request(new URL(`/api/v1${path}`, f.origin), {
        method,
        headers: f.headers({ authorization: `Bearer ${proof}` }),
        ...(method === "GET" ? {} : { body: "{}" }),
      });
      expect(response.status).toBe(401);
    }
  });
  it("T-AC-783 T-AC-793 typed owner preparation survives replay and changed duplicates conflict", async () => {
    const control = client();
    const requested = await input();
    const key = randomUUID();
    const first = await control.prepareCodingTask(requested, key);
    expect(await control.prepareCodingTask(requested, key)).toEqual(first);
    expect(await control.codingPreparation(first.id)).toEqual(first);
    await expect(
      control.prepareCodingTask({ ...requested, input: "Changed" }, key),
    ).rejects.toMatchObject({ code: "IDEMPOTENCY_CONFLICT", status: 409 });
    expect((await control.codingOverview()).preparations).toHaveLength(1);
  });
  it("T-AC-781 strict owner validation rejects injected authority and missing idempotency", async () => {
    const requested = await input();
    const invalid = await post("/agents/coding/preparations", {
      ...requested,
      cwd: "D:/untrusted",
    });
    expect(invalid.status).toBe(422);
    const noKey = await app.request(new URL("/api/v1/agents/coding/preparations", f.origin), {
      method: "POST",
      headers,
      body: JSON.stringify(requested),
    });
    expect(noKey.status).toBe(400);
    expect((await client().codingOverview()).preparations).toHaveLength(0);
  });
  it("T-AC-787 T-AC-793 preserves an owner preparation when actual execution is unavailable", async () => {
    const control = client();
    const p = await control.prepareCodingTask(await input(), randomUUID());
    await expect(
      control.admitCodingTask({ preparationId: p.id, expectedHash: p.hash }, randomUUID()),
    ).rejects.toMatchObject({ code: "CAPABILITY_UNAVAILABLE", status: 503 });
    const overview = await control.codingOverview();
    expect(overview.preparations).toHaveLength(1);
    expect(overview.tasks).toHaveLength(0);
    expect(overview.capabilities.every((value) => !value.available)).toBe(true);
  });
  it("T-AC-781 rejects stale API versions before creating coding preparations", async () => {
    const requested = await input();
    const old = new Headers(headers);
    old.set(CONTROL_API_HEADER, "1.12");
    const response = await post("/agents/coding/preparations", requested, randomUUID(), old);
    expect(response.status).toBe(422);
    expect((await client().codingOverview()).preparations).toHaveLength(0);
  });
  it("T-AC-787 default startup has no coding configuration lookup or executable provider", async () => {
    expect(await codingStartupOptions({})).toEqual({});
    expect(
      (await client().codingOverview()).capabilities.every((capability) => !capability.available),
    ).toBe(true);
  });
  it("T-AC-787 invalid explicit coding startup leaves independent owner HTTP administration usable", async () => {
    const coding = await codingStartupOptions({
      GODSEYE_CODING_BINDINGS_FILE: "relative-synthetic-invalid.json",
    });
    const isolated = new InfrastructureEngine(f.store, { coding });
    const application = createApp(
      f.core,
      loadConfiguration({ GODSEYE_MODE: "local" }),
      f.identity,
      isolated.foundation,
      broker,
      isolated,
    );
    const control = createControlClient({
      baseUrl: f.origin,
      headers,
      fetch: async (request, init) => application.request(new Request(request, init)),
    });
    const project = await control.createProject(projectInput, randomUUID());
    expect((await control.listProjects()).map((value) => value.id)).toContain(project.id);
    const overview = await control.codingOverview();
    expect(overview.capabilities.every((capability) => !capability.available)).toBe(true);
    expect(JSON.stringify(overview)).not.toContain("relative-synthetic-invalid.json");
  });
});
